	LEVEL_32_HISTORY = "Unsere Verfolgung hat uns tief ins Herz des Vulkans geführt, wo einst ein längst vergessener Tempel den Flammen huldigte. Doch der Große Feuerdrache, einst ein neutraler Wächter dieser feurigen Tiefen, regt sich nun in unnatürlichem Zorn. Alles deutet darauf hin, dass Rotjunge seinen Willen verdorben hat. Einem Drachen gegenüberzutreten ist kein leichtes Unterfangen, aber wir haben keine Wahl. In den Kampf!",
