	ENEMY_UNBLINDED_ABOMINATION_STAGE_8_NAME = "Vorarbeiter Abscheulichkeit",
	BOSS_BULL_KING_DESCRIPTION = "Eine gnadenlose und autoritäre Führungspersönlichkeit, Kriegsveteran und pragmatischer Stratege. Einst ein Eidbruder von Sun Wukong, plant der Dämonenkönig nun, die himmlischen Sphären seines Rivalen zu stehlen. Berühmt für seine enorme Stärke, seine nachtragende Art und seine Kampfkunst.",
